import{_ as e,o as t,c as o,ag as r}from"./chunks/framework.qXLDknWC.js";const u=JSON.parse('{"title":"CharacterVault 1.3.0","description":"","frontmatter":{},"headers":[],"relativePath":"releases/v1.3.0.md","filePath":"releases/v1.3.0.md"}'),i={name:"releases/v1.3.0.md"};function s(l,a,n,h,c,d){return t(),o("div",null,[...a[0]||(a[0]=[r(`<h1 id="charactervault-1-3-0" tabindex="-1">CharacterVault 1.3.0 <a class="header-anchor" href="#charactervault-1-3-0" aria-label="Permalink to &quot;CharacterVault 1.3.0&quot;">​</a></h1><p>This release adds a standalone Lorebook Vault so books no longer have to live on a single character, a fuller SillyTavern World Info editor, and a fullscreen recursion map with a visual web of unlock paths and safe bulk flag edits.</p><p><strong>Try it:</strong> <a href="https://spaceman2408.github.io/CharacterVault" target="_blank" rel="noreferrer">https://spaceman2408.github.io/CharacterVault</a><strong>Docs:</strong> <a href="https://spaceman2408.github.io/CharacterVault/docs/" target="_blank" rel="noreferrer">https://spaceman2408.github.io/CharacterVault/docs/</a></p><hr><h2 id="highlights" tabindex="-1">Highlights <a class="header-anchor" href="#highlights" aria-label="Permalink to &quot;Highlights&quot;">​</a></h2><h3 id="lorebook-vault" tabindex="-1">Lorebook Vault <a class="header-anchor" href="#lorebook-vault" aria-label="Permalink to &quot;Lorebook Vault&quot;">​</a></h3><p>A second home vault, alongside Characters, for standalone lorebooks.</p><ul><li>Create, search, import, export, duplicate, and delete books independent of any character</li><li>Importing a book names it from the filename, including Windows copy suffixes like <code>(1)</code>, rather than the shorter name stored inside the JSON</li><li>SillyTavern book scan settings (<code>scan_depth</code>, <code>token_budget</code>, <code>recursive_scanning</code>) survive import and are written back on export</li><li>Full workspace for each book: the shared entry editor, Orion chat, and history/snapshots</li><li>Local IndexedDB only, same privacy model as character cards</li></ul><p><a href="/CharacterVault/docs/features/lorebook-vault">Lorebook Vault →</a></p><h3 id="linking-and-sync" tabindex="-1">Linking and sync <a class="header-anchor" href="#linking-and-sync" aria-label="Permalink to &quot;Linking and sync&quot;">​</a></h3><p>A character can link one library book, and multiple characters can share the same book.</p><ul><li>Linking a book to a character offers to copy that book onto the card, replacing whatever lorebook was already there</li><li>While linked, edits made in the Lorebooks vault update every character that shares the book</li><li>&quot;Open in vault&quot; writes the character&#39;s current lorebook back to the library book, then opens it there</li><li>Detach a character at any time to stop it following the library book</li><li>Exporting a card includes the lorebook as it currently exists on that character, not a reference to the linked book</li></ul><p><a href="/CharacterVault/docs/features/lorebook-vault#attach-to-a-character-vault-local">Linking →</a></p><h3 id="lorebook-editor-shared" tabindex="-1">Lorebook editor (shared) <a class="header-anchor" href="#lorebook-editor-shared" aria-label="Permalink to &quot;Lorebook editor (shared)&quot;">​</a></h3><p>The character tab and vault books now share a single editor.</p><ul><li>Content first: title, keys, Enabled / Constant, and the content editor stay on screen at all times</li><li>Options and Attach are header buttons that open a panel over the editor; Done or Escape closes it</li><li>On a phone, the entry list and the editor swap places, and Attach sits next to book settings on the list</li><li>Supports the common SillyTavern fields: selective logic, recursion flags, probability, depth/role, match whole words, and book scan depth / token budget / recursive scanning</li><li>AI context usage bar and per-entry eye toggles, available with Character Vault AI</li><li>Books now come in through the Lorebooks vault and get attached from there. The editor no longer replaces the current book from a JSON file directly. Export is unchanged</li><li>Field help icons match the terms used in <a href="https://docs.sillytavern.app/usage/core-concepts/worldinfo/" target="_blank" rel="noreferrer">SillyTavern World Info</a></li></ul><p><a href="/CharacterVault/docs/features/lorebook-editor">Lorebook Editor →</a></p><h3 id="recursion-map" tabindex="-1">Recursion map <a class="header-anchor" href="#recursion-map" aria-label="Permalink to &quot;Recursion map&quot;">​</a></h3><p>A visual way to see which entries can trigger which, instead of guessing from a flat list.</p><ul><li>Web view lays out the whole book as a node graph, with arrows showing unlock paths, clustered by chain</li><li>Pan, zoom, and hover to spotlight a node&#39;s paths. Click to inspect and pin those paths, hover another node to temporarily override, and click again or use the inspector&#39;s X to clear. Ctrl-click to select multiple</li><li>Edit primary keys directly on the map. Changes write to the real entry and the arrows rebuild immediately</li><li>List view adds search and All / Linked / Standalone filters, and is used automatically as a fallback on large books</li><li>Per-entry flag toggles live right in the inspector and apply immediately</li><li>Bulk edits are staged first: pick a flag change, review exactly what will change and for how many entries, then apply or discard. Nothing changes silently</li><li>The camera holds its position when you inspect a node or when arrows change, and dense books wrap into tall ranks so pan and zoom stay smooth without redrawing every edge</li><li>This is an authoring aid based on primary keys found in content, not a full SillyTavern runtime simulation. The map only shows a recursion warning when a book has explicitly turned recursive scanning off</li></ul><p><a href="/CharacterVault/docs/features/lorebook-editor#recursion-map">Recursion map →</a> · <a href="/CharacterVault/docs/features/recursion-map-guide">Guide →</a></p><h3 id="snapshots" tabindex="-1">Snapshots <a class="header-anchor" href="#snapshots" aria-label="Permalink to &quot;Snapshots&quot;">​</a></h3><p>Standalone books get their own History modal. The &quot;Opened&quot; snapshot is the baseline: you can update it in place, but you cannot delete it. Save a snapshot when something actually changes, and restoring a book also updates every character linked to it.</p><p><a href="/CharacterVault/docs/features/snapshots-history#standalone-lorebook-snapshots">Snapshots →</a></p><hr><h2 id="upgrade" tabindex="-1">Upgrade <a class="header-anchor" href="#upgrade" aria-label="Permalink to &quot;Upgrade&quot;">​</a></h2><p>Client only app. Open the hosted site or rebuild locally.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/spaceman2408/CharacterVault</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> CharacterVault</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p>Existing character data and settings continue to work as is. IndexedDB gains lorebook tables the first time you open a build that includes this feature, through a schema migration. Export lorebook JSON if you want portable copies outside the browser.</p><p>Hard refresh if the UI looks stale after deploy.</p><hr><h2 id="docs" tabindex="-1">Docs <a class="header-anchor" href="#docs" aria-label="Permalink to &quot;Docs&quot;">​</a></h2><ul><li><a href="/CharacterVault/docs/features/lorebook-vault">Lorebook Vault</a></li><li><a href="/CharacterVault/docs/features/lorebook-editor">Lorebook Editor</a></li><li><a href="/CharacterVault/docs/features/recursion-map-guide">Recursion Map Guide</a></li><li><a href="/CharacterVault/docs/whats-new">What&#39;s New</a></li><li><a href="/CharacterVault/docs/changelog">Changelog</a></li></ul>`,33)])])}const k=e(i,[["render",s]]);export{u as __pageData,k as default};
